					return;
				}

				const knownIds = items.map( ( item ) => item.id );
				dispatch( {
					type: 'LOAD_SUCCESS',
					items,
					checked: ( postState.checked || [] ).filter( ( id ) =>
						knownIds.includes( id )
					),
				} );
			} catch ( error ) {
				if ( select.getPostId() === postId ) {
					dispatch( {
						type: 'LOAD_ERROR',
						error:
							error?.message ||
							__(
								'The editorial checklist could not be loaded.',
