			dispatch( { type: 'SET_CHECKED', checked: next } );
			dispatch( { type: 'SAVE_START' } );

			const save = saveQueue.then( () => {
				if ( select.getPostId() !== postId ) {
					return null;
				}
				return apiFetch( {
					path: `${ API_ROOT }/posts/${ postId }`,
					method: 'POST',
					data: { checked: select.getCheckedItemIds() },
				} );
			} );
